  late Future<List<dynamic>> _dashboardFuture;

  @override
  void initState() {
    super.initState();
    _initData();
  }

  void _initData() {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    _dashboardFuture = Future.wait([
      currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD')),
      newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
    ]);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.dashboardTitle)),
      body: FutureBuilder<List<dynamic>>(
        future: _dashboardFuture,
        builder: (BuildContext context, AsyncSnapshot<List<dynamic>> snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }

          if (!snapshot.hasData || snapshot.data!.isEmpty) {
            return Center(
              child: Text(context.loc.loadingData),
            );
          }

          final CurrencyPage currencyPage = snapshot.data![0] as CurrencyPage;
          final List<NewsModel> newsList = snapshot.data![1] as List<NewsModel>;

          return ListView(
            padding: const EdgeInsets.all(16),
            children: [
              _buildSectionTitle(context.loc.currencyRate),
              ...currencyPage.items.map((CurrencyModel currency) => Padding(
                    padding: const EdgeInsets.only(top: 8),
                    child: CurrencyCard(model: currency),
                  )),
              const SizedBox(height: 16),
              _buildSectionTitle(context.loc.news),
              ...newsList.map((NewsModel news) => Padding(
                    padding: const EdgeInsets.only(top: 8),
                    child: NewsCard(model: news),
                  )),
            ],
          );
        },
      ),
    );
  }

  Widget _buildSectionTitle(String title) {
    return Text(
      title,
      style: const TextStyle(fontSize: 20, fontWeight: FontWeight.bold),
    );
  }
}

