6: 
7:   @override
8:   State<DashboardPage> createState() => _DashboardPageState();
9: }
10: 
11: class _DashboardPageState extends State<DashboardPage> {
12:   late Future<List<dynamic>> _dashboardFuture;
13: 
14:   @override
15:   void initState() {
16:     super.initState();
17:     _initData();
18:   }
19: 
20:   void _initData() {
21:     final currencyRepository = context.read<CurrencyRepository>();
22:     final newsRepository = context.read<NewsRepository>();
23: 
24:     _dashboardFuture = Future.wait([
25:       currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD')),
26:       newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
27:     ]);
28:   }
29: 
30:   @override
31:   Widget build(BuildContext context) {
32:     return Scaffold(
33:       appBar: AppBar(title: Text(context.loc.dashboardTitle)),
34:       body: FutureBuilder<List<dynamic>>(
35:         future: _dashboardFuture,
36:         builder: (BuildContext context, AsyncSnapshot<List<dynamic>> snapshot) {
37:           if (snapshot.connectionState == ConnectionState.waiting) {
38:             return const Center(child: CircularProgressIndicator());
39:           }
40: 
41:           if (!snapshot.hasData || snapshot.data!.isEmpty) {
42:             return Center(
43:               child: Text(context.loc.loadingData),
44:             );
45:           }
46: 
47:           final CurrencyPage currencyPage = snapshot.data![0] as CurrencyPage;
48:           final List<NewsModel> newsList = snapshot.data![1] as List<NewsModel>;
49: 
50:           return ListView(
51:             padding: const EdgeInsets.all(16),
52:             children: [
53:               _buildSectionTitle(context.loc.currencyRate),
54:               ...currencyPage.items.map((CurrencyModel currency) => Padding(
55:                     padding: const EdgeInsets.only(top: 8),
56:                     child: CurrencyCard(model: currency),
57:                   )),
58:               const SizedBox(height: 16),
59:               _buildSectionTitle(context.loc.news),
60:               ...newsList.map((NewsModel news) => Padding(
61:                     padding: const EdgeInsets.only(top: 8),
62:                     child: NewsCard(model: news),
63:                   )),
64:             ],
65:           );
66:         },
67:       ),
68:     );
69:   }
70: 
